static void make_check_dir_subr(struct sr_ctx *c, uint8_t dirValue, int tileIndexAddValue) {
  // load current character id into x
  // LDA $7E00D5
  E(0xAF);
  E(0xD5);
  E(0x00);
  E(0x7E);
  // AND #00FF
  E(0x29);
  E(0xFF);
  E(0x00);
  // XBA
  E(0xEB);
  // TAX
  E(0xAA);
  // LDA $7EE002,X - load x position as map tile ref (divide 16)
  E(0xBF);
  E(0x02);
  E(0xE0);
  E(0x7E);
  // LSR 4 times
  E(0x4A);
  E(0x4A);
  E(0x4A);
  E(0x4A);
  // PHA
  E(0x48);
  // LDA $7EE004,X - load y position as map tile ref (divide 16)
  E(0xBF);
  E(0x04);
  E(0xE0);
  E(0x7E);
  // LSR 4 times
  E(0x4A);
  E(0x4A);
  E(0x4A);
  E(0x4A);
  // XBA
  E(0xEB);
  // LSR
  E(0x4A);
  // CLC
  E(0x18);
  // ADC $S,1 - combine with x for full tile ref id
  E(0x63);
  E(0x01);
  // PHA - shove it onto stack
  E(0x48);
  // SEP 20
  E(0xE2);
  E(0x20);
  // REP 20 .. hmm
  E(0xC2);
  E(0x20);
  // LDA #tileIndexAddValue
  E(0xA9);
  E((uint8_t)tileIndexAddValue);  // 0xFFFC = 4 tiles left, for example
  E((uint8_t)(tileIndexAddValue>>8));
  // clc and add our tile position to the one we generated based off direction
  // CLC
  E(0x18);
  // ADC $S,1
  E(0x63);
  E(0x01);
  // even out the stack by pulling x twice, and use our calculated value as x
  // PLX, PLX
  E(0xFA);
  E(0xFA);
  // TAX
  E(0xAA);
  // SEP 20
  E(0xE2);
  E(0x20);
  // check for map layer 1 or 2 for collisions
  // LDA $7E00DF
  E(0xAF);
  E(0xDF);
  E(0x00);
  E(0x7E);
  // AND #01
  E(0x29);
  E(0x01);
  // BEQ 06
  E(0xF0);
  E(0x06);
  // layer 2 collision - load from 7F:4000
  // LDA $7F4000,X
  E(0xBF);
  E(0x00);
  E(0x40);
  E(0x7F);
  // BRA 04
  E(0x80);
  E(0x04);
  // layer 1 collision - load from 7F:0000
  // LDA $7F0000,X
  E(0xBF);
  E(0x00);
  E(0x00);
  E(0x7F);
  // REP 20
  E(0xC2);
  E(0x20);
  // AND #00FF
  E(0x29);
  E(0xFF);
  E(0x00);
  // use the tile value * 4 as an index into a table at 7F:B800; if the [2,3] value is 6FF8 (which is an event reference on the collision data) we found a whip post
  // ASL, ASL
  E(0x0A);
  E(0x0A);
  // TAX
  E(0xAA);
  // LDA $7FB802,X
  E(0xBF);
  E(0x02);
  E(0xB8);
  E(0x7F);
  // CMP #6FF8 - check for whip destination tile
  E(0xC9);
  E(0xF8);
  E(0x6F);
  // BEQ 04 - jump to success case if match
  E(0xF0);
  E(0x04);
  // LDA #0002
  E(0xA9);
  E(0x02);
  E(0x00);
  // RTL
  E(0x6B);  // return from fail case
  // extra stuff here ..
  // heal statuses so we don't softlock when trying to teleport, take out everything but dead (8000)
  // success case: set the status flags that are normally cleared by event commands; it's faster to do it directly here than in the event
  // LDA $E190 - boy
  E(0xAD);
  E(0x90);
  E(0xE1);
  // AND #8000
  E(0x29);
  E(0x00);
  E(0x80);
  // STA $E190 - boy
  E(0x8D);
  E(0x90);
  E(0xE1);
  // LDA $E390 - girl
  E(0xAD);
  E(0x90);
  E(0xE3);
  // AND #8000
  E(0x29);
  E(0x00);
  E(0x80);
  // STA $E390 - girl
  E(0x8D);
  E(0x90);
  E(0xE3);
  // LDA $E590 - sprite
  E(0xAD);
  E(0x90);
  E(0xE5);
  // AND #8000
  E(0x29);
  E(0x00);
  E(0x80);
  // STA $E590 - sprite
  E(0x8D);
  E(0x90);
  E(0xE5);
  // set direction here
  // SEP 20
  E(0xE2);
  E(0x20);
  // LDA #dir
  E(0xA9);
  E(dirValue);
  // STA $E010 - boy
  E(0x8D);
  E(0x10);
  E(0xE0);
  // STA $E210 - girl
  E(0x8D);
  E(0x10);
  E(0xE2);
  // STA $E410 - sprite
  E(0x8D);
  E(0x10);
  E(0xE4);
  // REP 20
  E(0xC2);
  E(0x20);
  // LDA #1 - indicate success
  E(0xA9);
  E(0x01);
  E(0x00);
  // RTL
  E(0x6B);  // return from success case
}
